"""Individually written time-root lesson, without graphics."""
import json
from pathlib import Path
from lesson_authoring import entry as E
H=[['拉丁语 tempus，词干 tempor-','时间；时段']]
def D(h,a,b):return h+[[a,b]]
TEMP=H+[['拉丁 temporārius → 英语 temporary','只持续一段时间的 → 暂时的']]
CONT=H+[['中世纪拉丁 con- + temporārius → contemporārius','共同处在一个时期'],['英语 contemporary','同时代的；当代的；同代人']]
CONE=H+[['后期拉丁 contemporāneus → 英语 contemporaneous','同一时期的 → 同期发生或存在的']]
W=[
E('contemporary','英 /kənˈtempərəri/；美 /kənˈtempəreri/','当代的；同时代的；同代人','把两个人放到同一条时间线上，他们活跃的年代重合，就是 contemporaries。把参照点换成现在，便是“当代”。','来自中世纪拉丁 contemporārius；con- 共同 + temporārius 与时间有关。',CONT,'contemporary art 通常说当代艺术；a contemporary of Shakespeare 则是莎士比亚的同代人，不是今天的人。参照时代决定意思。','contemporary art；contemporary with；a contemporary of。','modern 常强调现代时代或风格；contemporary 可只是与某个历史人物处在同一时代。',('The gallery displays contemporary sculpture.','这家美术馆展出当代雕塑。'),('The writer was a contemporary of Charles Dickens.','这位作家与查尔斯·狄更斯生活在同一时代。'),sources=['https://www.etymonline.com/word/contemporary']),
E('temporary','英 /ˈtempərəri/；美 /ˈtempəreri/','暂时的；临时的','给某件事画一个时间框：现在先这样，过了这段时间会结束或改变。','借拉丁 temporārius，接 tempus“时间”；tempor- + -ary 可以帮助识别，但英语并不是从 time 拼出来。',TEMP,'temporary job 是临时工作，temporary solution 是权宜办法。这个词强调持续时间有限，不自动表示质量差。','temporary accommodation；a temporary measure；a temporary job。','brief 强调短；temporary 强调不会永久保持，临时安排也可能持续数月。',('We found temporary accommodation near the station.','我们在车站附近找到了临时住处。'),('The wooden bridge is only a temporary solution.','这座木桥只是临时解决办法。'),sources=['https://www.etymonline.com/word/temporary']),
E('temporarily','英 /ˈtempərərɪli/；美 /ˌtempəˈrerəli/','暂时；临时地','状态先停在这里一会儿，之后还有可能恢复或改变。','temporary 去掉词尾 y，改为 -ily；英语副词派生。',D(TEMP,'temporary → temporarily','暂时的 → 暂时地'),'temporarily closed 是暂时关闭，不是永远停业；具体多久要看告示。这个词不会给出确定的重开日期。','temporarily unavailable；temporarily closed；temporarily suspend。','temporarily 说持续时间有限；occasionally 说偶尔发生，回答的不是同一个问题。',('The library is temporarily closed for repairs.','图书馆因维修暂时关闭。'),('She is temporarily staying with her sister.','她暂时住在姐姐家。'),sources=['https://en.wiktionary.org/wiki/temporarily#English']),
E('tempo','英 /ˈtempəʊ/；美 /ˈtempoʊ/','速度；节奏快慢','同一首曲子可以慢慢弹，也可以快快弹；拍子前进多快，就是 tempo。','借意大利语 tempo“时间、速度”，来自拉丁 tempus。',[H[0],['意大利语 tempo','时间；音乐速度'],['英语 tempo','音乐速度；活动进展的快慢']],'音乐中常用每分钟拍数描述；一般文字也可说生活或比赛的推进速度。tempo 本身不说明节拍如何排列。','a slow tempo；increase the tempo；the tempo of life。','rhythm 是长短、强弱怎样排列；tempo 是这套排列走得多快。节奏型相同，速度仍能变化。',('The conductor asked the orchestra to keep a steady tempo.','指挥要求乐团保持稳定的速度。'),('The tempo of the game increased after the break.','休息过后，比赛节奏加快了。'),sources=['https://www.etymonline.com/word/tempo']),
E('temporal','英 /ˈtempərəl/；美 /ˈtempərəl/','时间的；世俗的；颞部的〔另一直接来源〕','把事件排在时间轴上，关注先后和长短，就是 temporal 角度；与永恒或宗教权威相对时，又可指尘世。','时间、世俗义接拉丁 temporālis ← tempus；解剖义接拉丁 tempora“太阳穴、颞部”，不能因拼写一样硬说脑区掌管时间。',[H[0],['拉丁 temporālis → 古法语 temporel → 英语 temporal','时间相关 → 时间的；尘世的'],['解剖义的另一支：拉丁 tempora → 中世纪拉丁 temporālis','太阳穴、颞部 → 颞部的']],'temporal order 是时间先后；temporal power 是世俗权力。temporal lobe 是颞叶，直接根据所在部位命名。这几义必须看搭配分开理解。','temporal sequence；temporal power；the temporal lobe。','temporary 是暂时的；temporal 是时间方面的。a temporal relation 不等于一种临时关系。',('The study examines the temporal order of the events.','研究考察这些事件发生的先后顺序。'),('The ruler held both spiritual and temporal power.','这位统治者同时掌握宗教和世俗权力。'),sources=['https://www.etymonline.com/word/temporal']),
E('contemporaneous','英 /kənˌtempəˈreɪniəs/；美 /kənˌtempəˈreɪniəs/','同时期的；同时发生的','两件事的时间范围重合，或者记录就是在事件发生那时写下的，可以用这个词强调“同一时期”。','接后期拉丁 contemporāneus；con- 共同 + tempus 时间，借入英语后成为较正式的形容词。',CONE,'contemporaneous notes 是当时作的记录，重点是离事件没有长久回忆的间隔。“同期”可以是一段时期，不必精确到同一秒。','contemporaneous with；contemporaneous records；contemporaneous accounts。','contemporary 可表示当代的；contemporaneous 通常着重两者同期，不用来泛指时髦的当代风格。',('The diary provides a contemporaneous account of the journey.','这本日记提供了旅行当时的记录。'),('The two settlements were roughly contemporaneous.','这两个聚落大致属于同一时期。'),sources=['https://www.etymonline.com/word/contemporaneous']),
E('contemporaneously','英 /kənˌtempəˈreɪniəsli/；美 /kənˌtempəˈreɪniəsli/','同时期地；在当时','不是多年后补写，而是在事情发生的那个时期就写下；这个副词把动作放回同一时间段。','contemporaneous + -ly，修饰记录、出版、发生等动作。',D(CONE,'英语 contemporaneous + -ly','同期的 → 同期地、在当时'),'常见于历史研究、正式记录。它强调时间上的对应；在普通会话里 at the time 或 at the same time 往往更自然。','recorded contemporaneously；published contemporaneously；contemporaneously with。','simultaneously 更容易指同一时刻或重叠进行；contemporaneously 也可以宽泛指同一时期。',('The observations were recorded contemporaneously in a notebook.','这些观察结果当时就记进了笔记本。'),('The two reports were published contemporaneously.','这两份报告在同一时期发表。'),sources=['https://en.wiktionary.org/wiki/contemporaneously#English']),
E('extemporaneous','英 /ɪkˌstempəˈreɪniəs/；美 /ekˌstempəˈreɪniəs/','即兴的；临场发挥的','眼前情况来了，你根据当下组织语言，不照着逐字写好的稿子念。','接后期拉丁 extemporāneus，来自短语 ex tempore“应时、临场”；ex- 在这里不是“前任”。',[H[0],['拉丁 ex tempore → 后期拉丁 extemporāneus','依眼前情势 → 临场的'],['英语 extemporaneous','即兴的；临场组织表达的']],'一般可指未经准备的即兴表达；在演讲训练中，也常指先研究、列提纲，再用自己的话说，所以不一定毫无准备。','an extemporaneous speech；extemporaneous remarks。','impromptu 常强调突然、未安排；extemporaneous 强调临场组织表达，专业演讲中可以有事前准备。',('She gave a brief extemporaneous response to the question.','她对这个问题作了简短的即兴回答。'),('He prepared an outline for his extemporaneous speech.','他为临场发挥的演讲准备了提纲。'),sources=['https://www.etymonline.com/word/extemporaneous','https://mdspeechanddebate.org/extemporaneous-speaking/']),
]
ROOT=dict(id='C1485',meaning='时间、时段；在同一时期或仅持续一段时间',core='TEMPOR = TIME',image='画一条时间轴：圈出一小段，是 temporary；把两个人放进同一段，是 contemporary；音乐沿着时间轴走得多快，是 tempo。',intro='来自拉丁 tempus“时间”，屈折形式中出现 tempor-。抓住时间范围，就能读懂这组词的大部分差别；不要把 tempor- 与 termin-“边界、终点”混为一谈。',forms='tempus 是拉丁基本形式，tempor- 是词干。tempo 经意大利语进入英语；contemporary 中 con- 表示共同。temporal 的解剖义直接接 tempora“太阳穴”，应和本页的时间主线区别说明。',branches=[['持续一段时间','temporary, temporarily'],['放在同一时代','contemporary, contemporaneous, contemporaneously'],['时间角度与推进快慢','temporal, tempo'],['顺应当下组织表达','extemporaneous']],contrasts='temporary 是暂时，temporal 是时间相关；contemporary 可指当代或某人的同代，contemporaneous 主要强调同期。tempo 是快慢，rhythm 是长短强弱怎样排列。',practice='The exhibition compares contemporary art with paintings by the artist’s contemporaries. The temporary display will remain open for two months.\n\n展览把当代艺术与这位画家同代人的作品作比较。这次临时展览将开放两个月。',words=[w['word'] for w in W])
if __name__=='__main__':
 target=Path(__file__).resolve().parents[1]/'.cache/batch200/drafts/root'
 for key,data in [('roots',[ROOT]),('words',W)]:
  (target/f'{key}_batch200_root_tempor.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
